## Complete Cookie Export Solution

```javascript
class CookieExporter {
    constructor() {
        this.timestamp = new Date().toISOString().replace(/[:.]/g, '-');
    }

    // Get all accessible cookies with detailed information
    getAllCookies() {
        const cookies = [];
        const cookieString = document.cookie;

        if (!cookieString) {
            return [{
                name: 'NO_COOKIES_FOUND',
                value: 'No accessible cookies found',
                domain: window.location.hostname,
                path: '/',
                timestamp: new Date().toISOString()
            }];
        }

        // Parse each cookie
        cookieString.split(';').forEach(cookie => {
            const [name, ...valueParts] = cookie.trim().split('=');
            const value = valueParts.join('='); // Handle values with = signs

            if (name) {
                cookies.push({
                    name: name.trim(),
                    value: value || '',
                    domain: window.location.hostname,
                    path: '/', // JavaScript can't access actual path info
                    secure: window.location.protocol === 'https:',
                    timestamp: new Date().toISOString(),
                    length: (value || '').length
                });
            }
        });

        return cookies;
    }

    // Create comprehensive debug report
    createDebugReport() {
        const cookies = this.getAllCookies();

        const report = {
            exportInfo: {
                timestamp: new Date().toISOString(),
                userAgent: navigator.userAgent,
                url: window.location.href,
                domain: window.location.hostname,
                protocol: window.location.protocol,
                cookieCount: cookies.length
            },
            sessionInfo: {
                sessionStorage: this.getSessionStorageInfo(),
                localStorage: this.getLocalStorageInfo(),
                cookiesEnabled: navigator.cookieEnabled
            },
            cookies: cookies,
            summary: this.generateSummary(cookies)
        };

        return report;
    }

    // Get session storage info for context
    getSessionStorageInfo() {
        try {
            const items = {};
            for (let i = 0; i < sessionStorage.length; i++) {
                const key = sessionStorage.key(i);
                items[key] = sessionStorage.getItem(key)?.substring(0, 100) + '...'; // Truncate for privacy
            }
            return {
                available: true,
                itemCount: sessionStorage.length,
                items: items
            };
        } catch (e) {
            return { available: false, error: e.message };
        }
    }

    // Get local storage info for context
    getLocalStorageInfo() {
        try {
            const items = {};
            for (let i = 0; i < localStorage.length; i++) {
                const key = localStorage.key(i);
                items[key] = localStorage.getItem(key)?.substring(0, 100) + '...'; // Truncate for privacy
            }
            return {
                available: true,
                itemCount: localStorage.length,
                items: items
            };
        } catch (e) {
            return { available: false, error: e.message };
        }
    }

    // Generate summary statistics
    generateSummary(cookies) {
        return {
            totalCookies: cookies.length,
            emptyCookies: cookies.filter(c => !c.value).length,
            largeCookies: cookies.filter(c => c.length > 1000).length,
            sessionCookies: cookies.filter(c => c.name.toLowerCase().includes('session')).length,
            authCookies: cookies.filter(c => 
                c.name.toLowerCase().includes('auth') || 
                c.name.toLowerCase().includes('token') ||
                c.name.toLowerCase().includes('login')
            ).length
        };
    }

    // Export as JSON file
    exportAsJSON() {
        const report = this.createDebugReport();
        const jsonString = JSON.stringify(report, null, 2);
        const filename = `cookie-debug-${this.timestamp}.json`;

        this.downloadFile(jsonString, filename, 'application/json');

        return report;
    }

    // Export as CSV file (simplified format)
    exportAsCSV() {
        const cookies = this.getAllCookies();
        const headers = ['Name', 'Value', 'Domain', 'Length', 'Timestamp'];

        let csvContent = headers.join(',') + '\n';

        cookies.forEach(cookie => {
            const row = [
                `"${cookie.name}"`,
                `"${cookie.value.replace(/"/g, '""')}"`, // Escape quotes
                `"${cookie.domain}"`,
                cookie.length,
                `"${cookie.timestamp}"`
            ];
            csvContent += row.join(',') + '\n';
        });

        const filename = `cookie-debug-${this.timestamp}.csv`;
        this.downloadFile(csvContent, filename, 'text/csv');

        return csvContent;
    }

    // Export as readable text report
    exportAsText() {
        const report = this.createDebugReport();

        let textContent = `COOKIE DEBUG REPORT\n`;
        textContent += `Generated: ${report.exportInfo.timestamp}\n`;
        textContent += `URL: ${report.exportInfo.url}\n`;
        textContent += `Domain: ${report.exportInfo.domain}\n`;
        textContent += `User Agent: ${report.exportInfo.userAgent}\n`;
        textContent += `Cookies Enabled: ${report.sessionInfo.cookiesEnabled}\n\n`;

        textContent += `SUMMARY:\n`;
        textContent += `Total Cookies: ${report.summary.totalCookies}\n`;
        textContent += `Empty Cookies: ${report.summary.emptyCookies}\n`;
        textContent += `Large Cookies (>1KB): ${report.summary.largeCookies}\n`;
        textContent += `Session-related Cookies: ${report.summary.sessionCookies}\n`;
        textContent += `Auth-related Cookies: ${report.summary.authCookies}\n\n`;

        textContent += `DETAILED COOKIE LIST:\n`;
        textContent += `${'='.repeat(50)}\n`;

        report.cookies.forEach((cookie, index) => {
            textContent += `${index + 1}. ${cookie.name}\n`;
            textContent += `   Value: ${cookie.value}\n`;
            textContent += `   Length: ${cookie.length} characters\n`;
            textContent += `   Domain: ${cookie.domain}\n`;
            textContent += `   Timestamp: ${cookie.timestamp}\n`;
            textContent += `   ${'-'.repeat(30)}\n`;
        });

        const filename = `cookie-debug-${this.timestamp}.txt`;
        this.downloadFile(textContent, filename, 'text/plain');

        return textContent;
    }

    // Utility method to trigger file download
    downloadFile(content, filename, mimeType) {
        const blob = new Blob([content], { type: mimeType });
        const url = URL.createObjectURL(blob);

        const link = document.createElement('a');
        link.href = url;
        link.download = filename;
        link.style.display = 'none';

        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);

        // Clean up the URL object
        setTimeout(() => URL.revokeObjectURL(url), 100);
    }

    // Console logging for immediate debugging
    logToConsole() {
        const report = this.createDebugReport();

        console.group('🍪 Cookie Debug Report');
        console.log('Export Info:', report.exportInfo);
        console.log('Session Info:', report.sessionInfo);
        console.log('Summary:', report.summary);
        console.table(report.cookies);
        console.groupEnd();

        return report;
    }
}

// Usage examples
const exporter = new CookieExporter();

// Quick console debug
exporter.logToConsole();

// Export files
exporter.exportAsJSON();  // Detailed JSON report
exporter.exportAsCSV();   // Simple CSV format
exporter.exportAsText();  // Human-readable text
```

