Absolutely! Here are practical examples of working with cookies in client-side JavaScript:

## Reading Cookies

```javascript
// Basic function to get a specific cookie
function getCookie(name) {
    const value = `; ${document.cookie}`;
    const parts = value.split(`; ${name}=`);
    if (parts.length === 2) {
        return parts.pop().split(';').shift();
    }
    return null;
}

// Usage
const userTheme = getCookie('theme');
console.log(userTheme); // Returns cookie value or null
```

## Setting Cookies

```javascript
// Basic cookie setting
function setCookie(name, value, days = 7) {
    const expires = new Date();
    expires.setTime(expires.getTime() + (days * 24 * 60 * 60 * 1000));
    document.cookie = `${name}=${value};expires=${expires.toUTCString()};path=/`;
}

// Usage
setCookie('theme', 'dark', 30); // Set for 30 days
```

## More Advanced Cookie Management

```javascript
// Comprehensive cookie utility
const CookieManager = {
    set(name, value, options = {}) {
        let cookieString = `${name}=${encodeURIComponent(value)}`;

        if (options.days) {
            const expires = new Date();
            expires.setTime(expires.getTime() + (options.days * 24 * 60 * 60 * 1000));
            cookieString += `;expires=${expires.toUTCString()}`;
        }

        cookieString += `;path=${options.path || '/'}`;

        if (options.secure) cookieString += ';secure';
        if (options.sameSite) cookieString += `;samesite=${options.sameSite}`;

        document.cookie = cookieString;
    },

    get(name) {
        const value = `; ${document.cookie}`;
        const parts = value.split(`; ${name}=`);
        if (parts.length === 2) {
            return decodeURIComponent(parts.pop().split(';').shift());
        }
        return null;
    },

    delete(name, path = '/') {
        document.cookie = `${name}=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=${path}`;
    },

    getAll() {
        return document.cookie.split(';').reduce((cookies, cookie) => {
            const [name, value] = cookie.trim().split('=');
            if (name) cookies[name] = decodeURIComponent(value || '');
            return cookies;
        }, {});
    }
};

// Usage examples
CookieManager.set('userPrefs', JSON.stringify({theme: 'dark', lang: 'en'}), {
    days: 365,
    secure: true,
    sameSite: 'strict'
});

const prefs = JSON.parse(CookieManager.get('userPrefs') || '{}');
console.log(prefs);
```

## Important Limitations

- **HttpOnly cookies**: Cannot be accessed via JavaScript (security feature)
- **Cross-domain restrictions**: Can only access cookies for current domain
- **Size limits**: Keep individual cookies under 4KB
- **Encoding**: Always encode/decode values to handle special characters

## Alternative: Using localStorage for simpler cases

```javascript
// Often easier for client-side data
localStorage.setItem('userTheme', 'dark');
const theme = localStorage.getItem('userTheme');
```

The cookie approach is best when you need the data sent to your server with each request, while localStorage is better for purely client-side data persistence.

