    <input 
        type="email" 
        name="username"
        id="username"
        autocomplete="username"
        placeholder="Email address"
        required
    >
    <input 
        type="password" 
        name="password"
        id="password"
        autocomplete="current-password"
        placeholder="Password"
        required
    >
