```javascript
// Quick one-liners for debugging
const quickCookieDebug = () => {
    const cookies = document.cookie.split(';').map(c => {
        const [name, value] = c.trim().split('=');
        return { name, value, length: (value || '').length };
    });

    console.table(cookies);
    return cookies;
};

// Check for specific session-related cookies
const checkSessionCookies = () => {
    const sessionCookies = document.cookie
        .split(';')
        .filter(cookie => {
            const name = cookie.trim().split('=')[0].toLowerCase();
            return name.includes('session') || 
                   name.includes('auth') || 
                   name.includes('token') ||
                   name.includes('login');
        });

    console.log('Session-related cookies:', sessionCookies);
    return sessionCookies;
};

// Monitor cookie changes
const monitorCookieChanges = () => {
    let lastCookieString = document.cookie;

    setInterval(() => {
        if (document.cookie !== lastCookieString) {
            console.log('Cookie change detected!');
            console.log('Before:', lastCookieString);
            console.log('After:', document.cookie);
            lastCookieString = document.cookie;
        }
    }, 1000);
};
