## Usage for Session Debugging

```javascript
// Add this to your page for debugging
window.debugCookies = () => {
    const exporter = new CookieExporter();

    // Log to console immediately
    const report = exporter.logToConsole();

    // Also export files
    exporter.exportAsJSON();

    // Check for common session issues
    if (report.summary.sessionCookies === 0) {
        console.warn('⚠️ No session cookies found - this might explain logout issues');
    }

    if (!report.sessionInfo.cookiesEnabled) {
        console.error('❌ Cookies are disabled in browser');
    }

    return report;
};

// Call it: debugCookies()
